package com.shield.domain;

/**
 * Categorises maintenance notifications generated by the system.
 * These are in-application notifications only. No external SMS or email
 * is sent unless a real external provider is configured.
 */
public enum NotificationType {
    FAULT_DETECTED,
    FAULT_LOCALIZED,
    SEGMENT_ISOLATED,
    BACKUP_ACTIVATED,
    REROUTING_FAILED,
    FAULT_CLEARED,
    SYSTEM_NORMAL,
    RELAY_OPERATED,
    MEASUREMENT_ANOMALY
}
